  const rd = $('sRadio'); rd.checked = G.set.radio !== false; rd.onchange = () => { G.set.radio = rd.checked; if (!rd.checked) RADIO.stop(); localStorage.setItem('inkstrike', JSON.stringify(G.set)); };
  const xs = $('sXhStatic'); xs.checked = !!G.set.xhStatic; xs.onchange = () => { G.set.xhStatic = xs.checked ? 1 : 0; localStorage.setItem('inkstrike', JSON.stringify(G.set)); };
  for (const [id, key, fn] of [['sSens', 'sens', v => v], ['sFov', 'fov', v => v], ['sVol', 'vol', v => { SFX.setVol(v); return v; }], ['sXhSize', 'xhSize', v => v], ['sMotion', 'motion', v => v], ['sInkFx', 'inkFx', v => v]]) { const el = $(id), lab = $(id + 'V'); el.value = G.set[key]; lab.textContent = G.set[key]; el.oninput = () => { G.set[key] = fn(+el.value); lab.textContent = el.value; localStorage.setItem('inkstrike', JSON.stringify(G.set)); }; }
