/* ---------------- camera + frame ---------------- */
function updateCamera(dt) {
  const pl = G.player; let fov = G.set.fov; G.shake = damp(G.shake, 0, 9, dt);
  if (pl.alive) { G.spec = null; camera.position.set(pl.pos.x, pl.pos.y + eyeY(pl) + pl.stepSmooth, pl.pos.z); const motion = G.set.motion, sh = G.shake * .012 * motion; camera.rotation.set(pl.pitch + pl.recP + pl.punch * .5 * motion + gauss() * sh, pl.yaw + pl.recY + gauss() * sh, (pl.roll + pl.punch * .3) * motion); if (pl.scoped) { const w = WEAPONS[pl.cur]; fov = w.scope ? (pl.scoped === 1 ? 46 : 26) : Math.min(G.set.fov * .84, w.adsFov || 66); } }
  else if (G.deathCam) { const d = G.deathCam; d.t += dt; if (d.t < 2.6 || G.mode === 'dm') { const h = Math.min(3.2, .4 + d.t * 1.6), bx = pl.pos.x + Math.sin(d.yaw) * h * .8, bz = pl.pos.z + Math.cos(d.yaw) * h * .8; camera.position.set(bx, pl.pos.y + h, bz); camera.lookAt(pl.pos.x, pl.pos.y + .3, pl.pos.z); }
    else { if (!G.spec || !G.spec.alive) cycleSpectator(1);
      if (G.spec) { const s = G.spec, bx = s.pos.x + Math.sin(s.yaw) * 2.6, bz = s.pos.z + Math.cos(s.yaw) * 2.6; _cv.set(bx, s.pos.y + 2.1, bz); const ok = segClear(s.pos.x, s.pos.y + 1.6, s.pos.z, bx, s.pos.y + 2.1, bz); if (!ok) _cv.set(s.pos.x, s.pos.y + 2.3, s.pos.z); camera.position.lerp(_cv, 1 - Math.exp(-8 * dt)); camera.rotation.set(damp(camera.rotation.x, s.pitch - .18, 8, dt), camera.rotation.y + angDiff(s.yaw, camera.rotation.y) * (1 - Math.exp(-8 * dt)), 0); } } }
  if (Math.abs(camera.fov - fov) > .05) { camera.fov = damp(camera.fov, fov, 22, dt); camera.updateProjectionMatrix(); }
  SFX.L.x = camera.position.x; SFX.L.z = camera.position.z; SFX.L.yaw = camera.rotation.y;
}
function frame(dt) {
  if (G.state === 'menu') { if (camera.fov !== G.set.fov) { camera.fov = G.set.fov; camera.updateProjectionMatrix(); } const t = G.now * .04; const m = MAP.menuCamera; camera.position.set(m.pos[0] + Math.sin(t) * 2, m.pos[1], m.pos[2]); camera.lookAt(...m.target); renderer.clear(); renderer.render(scene, camera); return; }
  if (!G.paused && G.state !== 'matchEnd') { const sdt = dt * G.timescale; G.now += sdt; updateFlow(sdt); const pl = G.player;
    if (G.state !== 'matchEnd' && G.state !== 'menu') { if (TOUCH.on) updateTouch(sdt); if (pl.alive) updatePlayer(sdt); TRAIN.update(sdt); for (const b of G.bots) updateBot(b, sdt, G.now); updateNades(sdt); bombUpdate(sdt); smokeUpdate(sdt); FX.update(sdt, camera); updateCamera(sdt); VM.update(sdt, pl, WEAPONS[pl.cur], G.mdx, G.mdy); updateHUD(dt);
      if (G.now - (G._spotT || 0) > .2) { G._spotT = G.now; if (pl.alive) for (const e of G.ents) if (e.alive && e.team !== pl.team && botSee(pl, e)) { const a = Math.abs(angDiff(Math.atan2(-(e.pos.x - pl.pos.x), -(e.pos.z - pl.pos.z)), pl.yaw)); if (a < 1 && !(G.flashT > .15)) markSpotted(e, pl.team, G.now); } } }
    G.mdx = G.mdy = 0; G.fireEdge = G.altEdge = false; }
  renderer.clear(); renderer.render(scene, camera); if (G.player && G.player.alive) { renderer.clearDepth(); renderer.render(VM.scene, VM.cam); }
}

/* ---------------- field map + adaptive roster ---------------- */
function addRosterBot(team, money) { const n = G.botSerial++, name = BOT_NAMES[n % BOT_NAMES.length] + (n >= BOT_NAMES.length ? ' ' + (1 + Math.floor(n / BOT_NAMES.length)) : ''), b = makeBot(team, name, scene); b.money = money; G.ents.push(b); G.bots.push(b); return b; }
function resizeRoster(size) { for (const team of ['blue', 'red']) { const want = size - (team === G.team ? 1 : 0), list = G.bots.filter(b => b.team === team), cash = Math.round(list.reduce((n, b) => n + b.money, 0) / Math.max(1, list.length)); while (list.length > want) { const b = list.pop(); scene.remove(b.model.root); G.ents.splice(G.ents.indexOf(b), 1); G.bots.splice(G.bots.indexOf(b), 1); disposeBotModel(b); } while (list.length < want) list.push(addRosterBot(team, Math.max(800, cash))); } G.teamSize = size; G.set.autoTeamSize = size; G.perf.pending = null; G.perf.samples = []; G.perf.cpu = []; G.perf.elapsed = 0; localStorage.setItem('inkstrike', JSON.stringify(G.set)); }
function samplePerformance(elapsed, cpu) { if (G.manualStep || G.state !== 'live' || G.paused || G.buyOpen || G.mapOpen || document.hidden || G.mode === 'range' || elapsed < 1) return; const p = G.perf; p.samples.push(Math.min(1000, elapsed)); p.cpu.push(cpu); p.elapsed += elapsed; if (p.samples.length < 300 && (p.elapsed < 8000 || p.samples.length < 30)) return; const sorted = p.samples.slice().sort((a, b) => a - b), costs = p.cpu.slice().sort((a, b) => a - b); p.p90 = sorted[Math.floor(sorted.length * .9)]; p.ms = costs[Math.floor(costs.length * .9)]; p.samples = []; p.cpu = []; p.elapsed = 0; if (G.set.battleSize !== 'auto') return; const steps = [5, 8, 12], i = steps.indexOf(G.teamSize), next = p.p90 > 28 || p.ms > 20 ? steps[Math.max(0, i - 1)] : p.p90 < 19 && p.ms < 10 ? steps[Math.min(2, i + 1)] : G.teamSize; p.pending = next === G.teamSize ? null : next; G.set.autoTeamSize = next; localStorage.setItem('inkstrike', JSON.stringify(G.set)); }
function updateBrief() { const mode = G.mode, count = G.set.battleSize === 'auto' ? '自动人数' : `${G.set.battleSize}v${G.set.battleSize}`; $('briefTitle').textContent = mode === 'range' ? '靶场 / 每一笔，都可控' : mode === 'dm' ? `死斗 / ${count}` : `竞技 / ${count}`; $('briefText').textContent = mode === 'range' ? '五档距离假人，固定弹道墙。免费取枪，找到属于你的压枪节奏。' : mode === 'dm' ? '无限重生，随时换装。率先拿下 40 次击倒的队伍获胜。' : G.team === 'red' ? '掩护墨核携带者，前往 A 或 B。按住互动键 3.2 秒完成安放。' : '守住两个点位，听声转点。墨核安放后，按住互动键 6 秒拆除。'; $('sizeHint').textContent = G.set.battleSize === 'auto' ? '按实战帧耗时调整 · 竞技在下一回合生效' : '手动固定人数 · 若帧率下降可选择自动'; $('optSize').parentElement.style.display = mode === 'range' ? 'none' : ''; if (MAP.mini) $('briefMap').src = MAP.mini.toDataURL(); $('fieldName').textContent = MAP.name; $('fieldEn').textContent = MAP.en; $('briefMap').alt = MAP.name + '地图概览'; $('mapTitle').textContent = MAP.name + ' / 战术地图'; $('mapNotes').textContent = MAP_CATALOG[MAP.id].description; $('sMap').value = MAP.id; }
function toggleMap(force) { const on = force === undefined ? !G.mapOpen : force; if (on && G.paused) return; G.mapOpen = on; $('rangeControls').hidden = G.mode !== 'range' || G.state !== 'live'; $('squadControls').hidden = G.mode !== 'comp' || G.state === 'menu'; $('tactical').classList.toggle('on', on); if (on) { G.buyOpen = false; $('buy').classList.remove('on'); unlockUI(); drawTactical(); } else { clearInput(); if (G.state !== 'menu' && !G.paused) lock(); } }
function drawTactical() { const c = $('tacticalMap'), g = c.getContext('2d'), sx = c.width / 128, sz = c.height / 112, point = (x, z) => [(x + 64) * sx, (z + 56) * sz]; g.clearRect(0, 0, c.width, c.height); g.drawImage(MAP.mini, 0, 0, c.width, c.height); g.font = 'bold 17px monospace'; g.textAlign = 'center'; for (const [label, x, z, col] of [['蓝方', (MAP.spawn.blue.x1 + MAP.spawn.blue.x2) / 2, (MAP.spawn.blue.z1 + MAP.spawn.blue.z2) / 2, '#2d6cb3'], ['红方', (MAP.spawn.red.x1 + MAP.spawn.red.x2) / 2, (MAP.spawn.red.z1 + MAP.spawn.red.z2) / 2, '#d42a2a']]) { const [px, py] = point(x, z); g.fillStyle = col; g.fillRect(px - 23, py - 14, 46, 28); g.fillStyle = label.length === 1 ? '#16161c' : '#f5f2ea'; g.fillText(label, px, py + 6); } if (G.state === 'menu') return; for (const e of G.ents) { const mine = e.team === G.team; if (!e.alive || !mine) continue; const ep = e.pos, [x, y] = point(ep.x, ep.z); g.save(); g.translate(x, y); g.rotate(-e.yaw); g.fillStyle = e.team === 'blue' ? '#2d6cb3' : '#d42a2a'; g.strokeStyle = '#f5f2ea'; g.lineWidth = 2; g.beginPath(); if (e.isPlayer) { g.moveTo(0, -9); g.lineTo(7, 7); g.lineTo(0, 3); g.lineTo(-7, 7); g.closePath(); } else g.arc(0, 0, 5, 0, Math.PI * 2); g.fill(); g.stroke(); g.restore(); } if (G.mode === 'comp' && (BOMB.state === 'planted' || BOMB.state === 'dropped' && G.team === 'red')) { const [x, y] = point(BOMB.pos.x, BOMB.pos.z); g.fillStyle = '#e9a520'; g.fillRect(x - 5, y - 5, 10, 10); } }
window.render_game_to_text = () => JSON.stringify({ coordinates: 'meters; x east, y up, z south; north is -z', state: G.state, mode: G.mode, teamSize: G.teamSize, paused: G.paused, buyOpen: G.buyOpen, mapOpen: G.mapOpen, score: G.score, round: G.round, player: G.player && { position: G.player.pos, alive: G.player.alive, hp: G.player.hp, weapon: G.player.cur, ammo: G.player.ammo[G.player.cur], yaw: G.player.yaw, pitch: G.player.pitch }, bots: G.bots.length, objective: { state: BOMB.state, site: BOMB.site, seconds: BOMB.t }, training: G.mode === 'range' ? TRAIN.snapshot() : null, order: G.order || null, spawnProtection: G.player ? Math.max(0, (G.player.spawnProtectedUntil || 0) - G.now) : 0, performance: { p90: G.perf.p90, cpuP90: G.perf.ms, nextTeamSize: G.perf.pending } });
window.advanceTime = ms => { G.manualStep = true; for (let i = 0, n = Math.max(1, Math.round(ms / (1000 / 60))); i < n; i++) frame(1 / 60); };
addEventListener('blur', () => { if (TOUCH.on && TOUCH.edit) return; clearInput(); if (G.state !== 'menu' && G.state !== 'matchEnd') setPause(true); });
document.addEventListener('visibilitychange', () => { if (TOUCH.on && TOUCH.edit) return; if (document.hidden && G.state !== 'menu' && G.state !== 'matchEnd') setPause(true); });

/* Device-calibrated input; no inertial tail or global screen-space delta in unlocked mode. */
const LOOK = { x: null, y: null, native: false, skip: 0 };
function resetLook() { LOOK.x = LOOK.y = null; LOOK.skip = 1; }
function mouseLook(e) { const pl = G.player; if (TOUCH.on || !locked() || !pl || !pl.alive || G.keys.KeyH || (e.target.closest && e.target.closest('button,input,select,.ov'))) { LOOK.x = LOOK.y = null; return; } const native = document.pointerLockElement === renderer.domElement; let dx, dy; if (native !== LOOK.native) { LOOK.native = native; resetLook(); } if (native) { dx = e.movementX; dy = e.movementY; if (LOOK.skip) { LOOK.skip--; return; } } else { const x = e.clientX, y = e.clientY; if (LOOK.x === null) { LOOK.x = x; LOOK.y = y; return; } dx = x - LOOK.x; dy = y - LOOK.y; LOOK.x = x; LOOK.y = y; } if (!Number.isFinite(dx) || !Number.isFinite(dy)) return; const d = Math.hypot(dx, dy), pad = G.set.aimMode === 'trackpad'; if (d > (pad ? 180 : 500)) return; const cap = pad ? 65 : 180, f = d > cap ? cap / d : 1, k = (pad ? .00105 : .0021) * G.set.sens * (camera.fov / G.set.fov); dx *= f; dy *= f; pl.yaw -= dx * k; pl.pitch = clamp(pl.pitch - dy * k, -1.54, 1.54); G.mdx += dx; G.mdy += dy; }
function cycleSpectator(dir = 1) { const pl = G.player; if (!pl || pl.alive || G.mode !== 'comp' || G.state === 'menu') return false; const mates = G.ents.filter(e => e !== pl && e.alive && e.team === pl.team), i = mates.indexOf(G.spec); G.spec = mates.length ? mates[(i < 0 ? (dir < 0 ? mates.length - 1 : 0) : (i + dir + mates.length) % mates.length)] : null; if (G.deathCam) G.deathCam.t = Math.max(2.6, G.deathCam.t); $('deadBy').textContent = G.spec ? `观战中 · ${G.spec.name} · ← / → 或按钮切换` : '暂无存活队友'; $('specLabel').textContent = G.spec ? G.spec.name + ' · ' + Math.ceil(G.spec.hp) + ' HP' : '等待回合结束'; G.fire = G.fireEdge = false; return !!G.spec; }
function updateActorPreview() { if (typeof ACTOR_STYLES === 'undefined') return; const sel = $('sActorStyle'); sel.innerHTML = ACTOR_STYLES.map(q => `<option value="${q.id}">${q.name}</option>`).join(''); const style = ACTOR_STYLES.find(q => q.id === G.set.actorStyle) || ACTOR_STYLES[0]; sel.value = style.id; $('actorDesc').textContent = style.desc + ' · 同步己方小队，轮廓与命中判定不变'; if (G.actorPreviews && G.actorPreviews[style.id]) $('actorPreview').src = G.actorPreviews[style.id]; }
